import logging
from taf.ue.spark.client.util import remove_escape_sequences


class RemoteWindowsEnvironment(object):
    def __init__(self, executor):
        self._executor = executor

    def get_pid_for_listening_port(self, service_port):
        command = 'netstat -ano|findstr "{}"'.format(service_port)
        logging.debug('sending {cmd}'.format(cmd=command))
        stat_str = self._executor.execute(command)
        logging.debug('recieved {}'.format(stat_str))
        # positive result should be like `TCP    0.0.0.0:30999          0.0.0.0:0              LISTENING       4596`
        if not stat_str:
            return None
        handled_stat = remove_escape_sequences(stat_str)
        lines = handled_stat.split("\r\n")
        for line in lines:
            line = line.strip()
            if not line:
                continue
            return int(line.split(" ")[-1])
        else:
            return None

    def is_app_pid(self, pid, appname):
        command = 'tasklist /NH /FI "PID eq {}" /FO CSV|findstr "{}"'.format(pid, appname)
        logging.debug('sending {cmd}'.format(cmd=command))
        result = self._executor.execute(command)
        logging.debug('recieved {}'.format(result))
        # positive result should be like `"RemoteService.exe","4596","Services","0","21,408 K"`
        handled_result = remove_escape_sequences(result).strip()
        return True if handled_result else False
